+      for (const c of candidates) {
+        if (!deps.refExists(opts.repoRoot, c)) {
+          tried.push(`${c} (not found)`);
+          continue;
+        }
+        try {
+          text = deps.gitShow(opts.repoRoot, c);
+          source = "base-ref";
+          ref = c;
+          break;
+        } catch (err) {
+          tried.push(`${c} (${(err instanceof Error ? err.message : String(err)).split("\n")[0].slice(0, 120)})`);
+        }
+      }
