+    if (isLocalVoice(m.provider, m.model_id, trusted)) kept.push(m);
+    else refused.push({ provider: m.provider, modelId: m.model_id, reason: localityRefusal(m.model_id, m.provider) });
+  }
+  return { kept, refused };
