+  /** `bridgebuilder.exit_on_degraded` (default 3; 0 restores the pre-cycle-129 exit). */
+  exitOnDegraded: number;
+  /** Lines to log once at startup (read failures, refusals, invalid values). */
+  warnings: string[];
 }

